import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { getUserRewardsHandler } from "../handlers/getUserRewardsHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof getUserRewardsHandler>>;

export function useGetUserRewards(
  username: string,
  month?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["getUserRewards", username, month],
    queryFn: () => getUserRewardsHandler(username, month),
    ...options,
  });
}
